import json

def main(response_json: str) -> dict:
    try:
        data = json.loads(response_json or '{}')
    except Exception:
        data = {
            'status': 'failed',
            'progress': 100,
            'result_url': '',
            'error': {'message': 'invalid JSON response'},
            'message': 'invalid JSON response',
        }
    error = data.get('error')
    if isinstance(error, dict):
        error_message = str(error.get('message') or error.get('detail') or '')
    else:
        error_message = str(error or '')
    result_url = str(
        data.get('result_url')
        or data.get('source_video_url')
        or data.get('english_srt_url')
        or data.get('bilingual_srt_url')
        or data.get('final_video_url')
        or ''
    )
    try:
        progress = int(data.get('progress') or 0)
    except Exception:
        progress = 0
    status = str(data.get('status') or '')
    detail = data.get('detail')
    if not status and detail:
        status = 'failed'
        progress = 100
        error_message = str(detail)
    if not status and error_message:
        status = 'failed'
        progress = 100
    return {
        'status': status,
        'progress': progress,
        'result_url': result_url,
        'error': error_message,
        'message': str(data.get('message') or ''),
    }

